"""Week 12 (Catalan bijections) math check: independent combinatorics.

Written for this review. It does not import the packet's builders or checkers.
Three objects are generated independently of one another:
  * all perfect matchings of 1..2n (brute force), filtered by an interleaving test;
  * all U/D words of length 2n (brute force over 2^(2n) strings), filtered by prefix heights;
  * ordered rooted trees, generated by compositions of the root's children
    (not by the first-return split the guide uses).
Then every answer the student pages imply and every claim the guides make is
recomputed.  Run: python3 catalan.py > catalan.out
"""
import itertools
from functools import lru_cache

FAIL = []


def check(name, ok, detail=''):
    print(('PASS ' if ok else 'FAIL ') + name + ((': ' + str(detail)) if detail != '' else ''))
    if not ok:
        FAIL.append(name)


# ------------------------------------------------------------------ matchings
def all_matchings(pts):
    pts = list(pts)
    if not pts:
        yield ()
        return
    a = pts[0]
    for i in range(1, len(pts)):
        rest = pts[1:i] + pts[i + 1:]
        for m in all_matchings(rest):
            yield tuple(sorted(((a, pts[i]),) + m))


def crosses(e, f):
    (a, b), (c, d) = sorted(e), sorted(f)
    return a < c < b < d or c < a < d < b


def noncrossing(m):
    return not any(crosses(e, f) for e, f in itertools.combinations(m, 2))


def nc_matchings(N):
    """Noncrossing perfect matchings of points 1..N (fixed labels)."""
    if N % 2:
        return []
    return [m for m in all_matchings(range(1, N + 1)) if noncrossing(m)]


def code_of_matching(m, N):
    first = {min(e) for e in m}
    return ''.join('U' if i in first else 'D' for i in range(1, N + 1))


def fmt(m):
    return '|'.join(f'{a}{b}' if b < 10 else f'{a}-{b}' for a, b in sorted(m))


# ------------------------------------------------------------------ words
def heights(w):
    h = [0]
    for c in w:
        h.append(h[-1] + (1 if c == 'U' else -1))
    return h


def is_dyck(w):
    h = heights(w)
    return min(h) >= 0 and h[-1] == 0


def dyck_words(n):
    return sorted(''.join(t) for t in itertools.product('UD', repeat=2 * n) if is_dyck(''.join(t)))


def matchings_with_code(w):
    """Every noncrossing matching of 1..len(w) whose U/D code is w (brute force, no stack rule)."""
    return [m for m in nc_matchings(len(w)) if code_of_matching(m, len(w)) == w]


# ------------------------------------------------------------------ ordered trees
@lru_cache(None)
def trees(n):
    """Ordered rooted trees with n edges, as nested tuples of children.
    Generated by choosing a composition of n into root-branch sizes (k_i+1)."""
    if n == 0:
        return ((),)
    out = []

    def comps(m):
        if m == 0:
            yield ()
            return
        for first in range(1, m + 1):
            for rest in comps(m - first):
                yield (first,) + rest

    for comp in comps(n):
        for kids in itertools.product(*[trees(s - 1) for s in comp]):
            out.append(tuple(kids))
    return tuple(out)


def walk(t):
    return ''.join('U' + walk(c) + 'D' for c in t)


def leaves(t):
    if not t:
        return 1
    return sum(leaves(c) for c in t)


def depth(t):
    return 0 if not t else 1 + max(depth(c) for c in t)


def tree_from_code_bruteforce(w):
    """All trees with len(w)/2 edges whose walk is w (search, not the guide's rule)."""
    return [t for t in trees(len(w) // 2) if walk(t) == w]


def nesting_depth(m):
    best = 0
    for e in m:
        d = 1 + sum(1 for f in m if f != e and min(f) < min(e) and max(e) < max(f))
        best = max(best, d)
    return best


def peaks(w):
    return sum(1 for i in range(len(w) - 1) if w[i:i + 2] == 'UD')


def returns(w):
    return sum(1 for h in heights(w)[1:] if h == 0)


print('== Catalan counts from three independent generators')
counts = {}
for n in range(0, 7):
    M = nc_matchings(2 * n)
    W = dyck_words(n)
    T = trees(n)
    counts[n] = (len(M), len(W), len(T))
    check(f'n={n}: matchings={len(M)} dyck={len(W)} trees={len(T)} all equal', len(M) == len(W) == len(T))
    # pairing -> code is a bijection onto Dyck words
    codes = sorted(code_of_matching(m, 2 * n) for m in M)
    check(f'n={n}: pairing codes are distinct and are exactly the Dyck words', codes == W)
    # tree -> walk is a bijection onto Dyck words
    walks = sorted(walk(t) for t in T)
    check(f'n={n}: tree walks are distinct and are exactly the Dyck words', walks == W)
    # statistics
    if n >= 1:
        ok = all(peaks(walk(t)) == leaves(t) for t in T)
        check(f'n={n}: peaks (UD) = leaves for every tree', ok)
        ok = all(max(heights(walk(t))) == depth(t) for t in T)
        check(f'n={n}: max height = tree depth for every tree', ok)
        ok = all(returns(walk(t)) == len(t) for t in T)
        check(f'n={n}: returns to zero = number of root children', ok)
        ok = all(max(heights(code_of_matching(m, 2 * n))) == nesting_depth(m) for m in M)
        check(f'n={n}: max height = deepest arc nesting for every pairing', ok)
check('counts are 1,1,2,5,14,42,132', [counts[n][0] for n in range(7)] == [1, 1, 2, 5, 14, 42, 132])

