check('C(6)=42+14+10+10+14+42', [C[i] * C[5 - i] for i in range(6)] == [42, 14, 10, 10, 14, 42] and C[6] == 132)

# Uniqueness of the inverse (brute force over all noncrossing matchings, no stack rule)
for n in range(1, 6):
    ok = all(len(matchings_with_code(w)) == 1 for w in dyck_words(n))
    check(f'n={n}: every Dyck word is the code of exactly one noncrossing pairing', ok)
    ok = all(len(tree_from_code_bruteforce(w)) == 1 for w in dyck_words(n))
    check(f'n={n}: every Dyck word is the walk of exactly one ordered tree', ok)
# Every U/D string of length 2n that is a code is a Dyck word (so "rules" are exactly the Dyck conditions)
for n in range(1, 6):
    allcodes = {code_of_matching(m, 2 * n) for m in all_matchings(range(1, 2 * n + 1))}
    check(f'n={n}: codes of ALL pairings (crossing allowed) are still exactly Dyck words', sorted(allcodes) == dyck_words(n))

