def unlike_pairings(word):
    N = len(word)
    return [m for m in nc_matchings(N) if all(word[a - 1] != word[b - 1] for a, b in m)]


for word, expect in [('RBRBRB', ['12|34|56', '12|36|45', '14|23|56', '16|23|45', '16|25|34']),
                     ('RRRBBB', ['16|25|34']), ('RRBRBB', ['16|23|45', '16|25|34'])]:
    got = sorted(fmt(m) for m in unlike_pairings(word))
    check(f'RV P1: {word} unlike pairings {got}', got == expect)
