check('RV P3: ceiling 2, five pairs -> 16', ceil_count(5, 2) == 16)


def blocks_ok(n):
    # each ground block of a ceiling-2 path is U (UD)^k D
    for w in dyck_words(n):
        if max(heights(w)) > 2:
            continue
        h = heights(w)
        cuts = [i for i, x in enumerate(h) if x == 0]
        for a, b in zip(cuts, cuts[1:]):
            blk = w[a:b]
            r = (b - a) // 2
            if blk != 'U' + 'UD' * (r - 1) + 'D':
                return False
    return True


check('RV guide: every ceiling-2 ground block is U (UD)^(r-1) D (n<=7)', all(blocks_ok(n) for n in range(1, 8)))


# swap graph: a move swaps adjacent unlike letters and must stay a Dyck path
def neighbours(w):
    out = []
    for i in range(len(w) - 1):
        if w[i] != w[i + 1]:
            v = w[:i] + w[i + 1] + w[i] + w[i + 2:]
            if is_dyck(v):
                out.append(v)
    return out


def bfs(src, n):
    dist = {src: 0}
    q = [src]
    for x in q:
        for y in neighbours(x):
            if y not in dist:
                dist[y] = dist[x] + 1
                q.append(y)
    return dist


def score(w):
    n = len(w) // 2
    m = heights('U' * n + 'D' * n)
    return sum(a - b for a, b in zip(m, heights(w))) // 2


def inversions(w):
    return sum(1 for i in range(len(w)) for j in range(i + 1, len(w)) if w[i] == 'D' and w[j] == 'U')


