for n in range(1, 7):
    Dn = bfs('U' * n + 'D' * n, n)
    ok = all(Dn[w] == score(w) == inversions(w) for w in dyck_words(n))
    check(f'RV guide: distance to mountain = half the height gap = D-before-U count (n={n})', ok)
