# the guide's caution: the mountain score alone does not give the distance between two arbitrary paths
for n in range(3, 6):
    W = dyck_words(n)
    allok = True
    score_fails = 0
    for a in W:
        Da = bfs(a, n)
        for b in W:
            l1 = sum(abs(x - y) for x, y in zip(heights(a), heights(b))) // 2
            allok &= Da[b] == l1
            score_fails += Da[b] != abs(score(a) - score(b))
    check(f'RV extension (n={n}): distance between any two paths = half the summed height gaps; '
          f'{score_fails} ordered pairs where the score difference is not the distance', allok and score_fails > 0)
